from collections import Counter
from robot import *

errors_by_hour = {}
messages = Counter()
with open("warden.log") as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        date, time, level, message = line.split(" ", 3)
        if level == "ERROR":
            hour = time[:2]
            errors_by_hour[hour] = errors_by_hour.get(hour, 0) + 1
            messages[message] += 1
top_error = messages.most_common(1)[0][0]
total = sum(errors_by_hour.values())
for hour in sorted(errors_by_hour):
    print(hour, errors_by_hour[hour])
if total >= 5:
    print("ALERT:", total, "errors")
while front() != "door":
    move()
unlock(top_error)
while not at_exit():
    move()

