from datetime import datetime, timedelta
from robot import *

def next_runs(start, count):
    runs = []
    t = start.replace(hour=7, minute=30, second=0, microsecond=0)
    if t <= start:
        t += timedelta(days=1)
    while len(runs) < count:
        if t.weekday() < 5:
            runs.append(t)
        t += timedelta(days=1)
    return runs

while here() != "terminal":
    move()
start = datetime.strptime(scan(), "%Y-%m-%d %H:%M")
for run in next_runs(start, 3):
    print(run.strftime("%a %d %b %H:%M"))
while not at_exit():
    move()
